CREATE TABLE "WorkspaceApiKey" ("id" UUID NOT NULL, "workspaceId" UUID NOT NULL, "createdByUserId" UUID NOT NULL, "name" TEXT NOT NULL, "prefix" TEXT NOT NULL, "secretHash" TEXT NOT NULL, "scopes" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[], "expiresAt" TIMESTAMP(3), "revokedAt" TIMESTAMP(3), "lastUsedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "WorkspaceApiKey_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "WorkspaceApiKey_secretHash_key" ON "WorkspaceApiKey"("secretHash");
CREATE UNIQUE INDEX "WorkspaceApiKey_workspaceId_name_key" ON "WorkspaceApiKey"("workspaceId", "name");
CREATE INDEX "WorkspaceApiKey_workspaceId_revokedAt_idx" ON "WorkspaceApiKey"("workspaceId", "revokedAt");
CREATE TABLE "OutboundWebhook" ("id" UUID NOT NULL, "workspaceId" UUID NOT NULL, "createdByUserId" UUID NOT NULL, "name" TEXT NOT NULL, "url" TEXT NOT NULL, "secretCiphertext" TEXT NOT NULL, "events" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[], "enabled" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "OutboundWebhook_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "OutboundWebhook_workspaceId_name_key" ON "OutboundWebhook"("workspaceId", "name"); CREATE INDEX "OutboundWebhook_workspaceId_enabled_idx" ON "OutboundWebhook"("workspaceId", "enabled");
CREATE TABLE "WebhookDelivery" ("id" UUID NOT NULL, "webhookId" UUID NOT NULL, "workspaceId" UUID NOT NULL, "eventId" TEXT NOT NULL, "eventType" TEXT NOT NULL, "payload" JSONB NOT NULL, "status" TEXT NOT NULL DEFAULT 'PENDING', "attempts" INTEGER NOT NULL DEFAULT 0, "nextAttemptAt" TIMESTAMP(3), "responseStatus" INTEGER, "errorCategory" TEXT, "deliveredAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "WebhookDelivery_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "WebhookDelivery_webhookId_eventId_key" ON "WebhookDelivery"("webhookId", "eventId"); CREATE INDEX "WebhookDelivery_workspaceId_status_nextAttemptAt_idx" ON "WebhookDelivery"("workspaceId", "status", "nextAttemptAt");
